fn cli_runtime_turn_start_request(
    request_id: &str,
    thread_id: &str,
    turn_id: &str,
    execution_backend: JsonValue,
    permission_mode: &str,
    text: &str,
    cli_runtime_options: Option<JsonValue>,
) -> String {
    let mut params = json!({
        "thread_id": thread_id,
        "turn_id": turn_id,
        "execution_backend": execution_backend,
        "permission_profile": {
            "mode": permission_mode
        },
        "input": [{
            "type": "text",
            "text": text
        }]
    });
    if let Some(options) = cli_runtime_options {
        params["cli_runtime_options"] = options;
    }
    json!({
        "jsonrpc": "2.0",
        "id": request_id,
        "method": "turn/start",
        "params": params
    })
    .to_string()
}

