#[test]
fn resilience_worker_pool_timeout_is_transient_storage_backpressure() {
    let error = anyhow::anyhow!(
        "failed to query expired running attempts: Failed to acquire connection from pool: \
         Connection pool timed out: Connection pool timed out"
    );
    let mut transient_storage_poll_failed = false;

    record_resilience_worker_poll_error(
        "timeout supervisor",
        &error,
        &mut transient_storage_poll_failed,
    );

    assert!(transient_storage_poll_failed);
}

#[test]
fn terminal_failure_paths_stay_behind_recovery_gate() {
    let leaf_sources = [
        ("turn_handlers.rs", include_str!("turn_handlers.rs")),
        ("artifact_tools.rs", include_str!("artifact_tools.rs")),
        (
            "task_agent_executor.rs",
            include_str!("task_agent_executor.rs"),
        ),
        ("mod.rs", include_str!("mod.rs")),
    ];

    for (name, source) in leaf_sources {
        assert!(
            !source.contains("mark_turn_failed_terminal("),
            "{name} must not bypass recovery with mark_turn_failed_terminal"
        );
        assert!(
            !source.contains("mark_turn_failed_with_recovery("),
            "{name} must not bypass recovery with mark_turn_failed_with_recovery"
        );
    }

    let runtime = include_str!("agent_runtime.rs");
    assert_eq!(
        runtime.matches(".mark_turn_failed_terminal(").count(),
        1,
        "terminal failure transition should only be requested from recovery exhaustion handling"
    );
    assert_eq!(
        runtime
            .matches("pub(super) async fn mark_turn_failed_terminal(")
            .count(),
        1,
        "terminal failure transition should have one centralized implementation"
    );
}

struct CompletingSystemExecutor;

#[async_trait]
impl pioneer_tasks::TaskExecutor for CompletingSystemExecutor {
    fn kind(&self) -> TaskExecutorKind {
        TaskExecutorKind::System
    }

    async fn start_run(
        &self,
        _context: pioneer_tasks::TaskExecutionContext,
        run: TaskRun,
        handle: pioneer_tasks::TaskExecutionHandle,
    ) -> pioneer_tasks::TaskRuntimeResult<pioneer_tasks::TaskExecutorStartOutcome> {
        handle.mark_started(run.created_at).await?;
        handle
            .complete_run(
                Some(TaskResult {
                    summary: Some("delivered scheduled result".to_owned()),
                    data: Some(TaskValue::Object(BTreeMap::from([(
                        "rawText".to_owned(),
                        TaskValue::String("delivered scheduled result\nfull detail".to_owned()),
                    )]))),
                    artifacts: Vec::new(),
                    completed_by_run_id: Some(run.id.clone()),
                }),
                run.created_at,
            )
            .await?;
        Ok(pioneer_tasks::TaskExecutorStartOutcome::Started)
    }

    async fn cancel_run(
        &self,
        _context: pioneer_tasks::TaskExecutionContext,
        _run_id: &str,
        _reason: &str,
        _handle: pioneer_tasks::TaskExecutionHandle,
    ) -> pioneer_tasks::TaskRuntimeResult<()> {
        Ok(())
    }
}

