#[tokio::test]
async fn memory_settings_update_reinstalls_memory_hook_runtime() {
    let mut harness = setup_memory_gateway_harness("settings_reinstall_memory_hooks", true).await;
    harness.processor.bind_memory_bridge_if_enabled().await;

    assert_memory_hook_subscription(&harness.processor, "memory.active_recall.default", true).await;
    assert_memory_hook_subscription(
        &harness.processor,
        "memory.post_turn_extractor.default",
        true,
    )
    .await;

    let disable_request_id = generate_test_request_id("settings", "disable_memory_hooks");
    let disable_request = json!({
        "jsonrpc": "2.0",
        "id": disable_request_id,
        "method": "settings/update",
        "params": {
            "update": {
                "memory": {
                    "enabled": true,
                    "deterministic_recall_enabled": true,
                    "active_recall_enabled": false,
                    "tools_enabled": true,
                    "proactive_writes_enabled": false,
                    "background_extraction_enabled": true,
                    "proactive_writes_model": {
                        "source": "thread"
                    },
                    "debug_trace_enabled": false,
                    "strict_diagnostics_enabled": false
                }
            }
        }
    });
    harness
        .processor
        .process_request(harness.connection_id, &disable_request.to_string())
        .await;
    let _ = recv_response_by_id(&mut harness.rx, disable_request_id.as_str()).await;

    assert_memory_hook_subscription(&harness.processor, "memory.active_recall.default", false)
        .await;
    assert_memory_hook_subscription(
        &harness.processor,
        "memory.post_turn_extractor.default",
        false,
    )
    .await;

    let enable_request_id = generate_test_request_id("settings", "enable_memory_hooks");
    let enable_request = json!({
        "jsonrpc": "2.0",
        "id": enable_request_id,
        "method": "settings/update",
        "params": {
            "update": {
                "memory": {
                    "enabled": true,
                    "deterministic_recall_enabled": true,
                    "active_recall_enabled": true,
                    "tools_enabled": true,
                    "proactive_writes_enabled": true,
                    "background_extraction_enabled": true,
                    "proactive_writes_model": {
                        "source": "custom",
                        "model_provider": "extractor-provider",
                        "model": "extractor-model"
                    },
                    "debug_trace_enabled": false,
                    "strict_diagnostics_enabled": false
                }
            }
        }
    });
    harness
        .processor
        .process_request(harness.connection_id, &enable_request.to_string())
        .await;
    let _ = recv_response_by_id(&mut harness.rx, enable_request_id.as_str()).await;

    assert_memory_hook_subscription(&harness.processor, "memory.active_recall.default", true).await;
    assert_memory_hook_subscription(
        &harness.processor,
        "memory.post_turn_extractor.default",
        true,
    )
    .await;
    let memory_config = harness.processor.memory_loop_config();
    assert_eq!(
        memory_config.post_turn_extractor.provider_name.as_deref(),
        Some("extractor-provider")
    );
    assert_eq!(
        memory_config.post_turn_extractor.model.as_deref(),
        Some("extractor-model")
    );
}

async fn assert_memory_hook_subscription(
    processor: &MessageProcessor,
    subscription_id: &str,
    expected_present: bool,
) {
    let runtime = processor
        .hook_runtime
        .read()
        .await
        .clone()
        .expect("memory hook runtime should be installed");
    let subscription_id =
        HookSubscriptionId::new(subscription_id).expect("test subscription id should be valid");
    let found = runtime
        .subscriptions()
        .get_subscription(&subscription_id)
        .expect("subscription lookup should succeed")
        .is_some();
    assert_eq!(
        found, expected_present,
        "unexpected presence for hook subscription `{subscription_id}`"
    );
}

impl SequencedToolProvider {
    fn new(first_tool_calls: Vec<ProviderToolCall>, second_text: impl Into<String>) -> Self {
        Self {
            requests: std::sync::Mutex::new(Vec::new()),
            first_tool_calls,
            second_text: second_text.into(),
            next_index: AtomicUsize::new(0),
        }
    }

    fn snapshot_requests(&self) -> Vec<ChatRequest> {
        self.requests
            .lock()
            .expect("sequenced tool provider lock poisoned")
            .clone()
    }
}

impl MemoryAgentE2eProvider {
    fn new(name: &'static str, script: MemoryAgentE2eScript) -> Self {
        Self {
            name,
            script,
            policy_requests: std::sync::Mutex::new(Vec::new()),
            main_requests: std::sync::Mutex::new(Vec::new()),
            next_main_index: AtomicUsize::new(0),
        }
    }

    fn snapshot_main_requests(&self) -> Vec<ChatRequest> {
        self.main_requests
            .lock()
            .expect("memory e2e provider main requests lock poisoned")
            .clone()
    }

    fn snapshot_policy_requests(&self) -> Vec<ChatRequest> {
        self.policy_requests
            .lock()
            .expect("memory e2e provider policy requests lock poisoned")
            .clone()
    }
}

#[async_trait::async_trait]
impl Provider for MemoryAgentE2eProvider {
    fn name(&self) -> &str {
        self.name
    }

    fn capabilities(&self) -> ProviderCapabilities {
        ProviderCapabilities {
            streaming: false,
            vision: false,
            tool_calling: false,
            embeddings: false,
            transcription: false,
            input_types: ProviderInputCapabilities::fallback_for_all_file_types(),
        }
    }

    async fn chat(&self, request: ChatRequest) -> anyhow::Result<ChatResponse> {
        if is_memory_policy_classifier_request(&request) {
            self.policy_requests
                .lock()
                .expect("memory e2e provider policy requests lock poisoned")
                .push(request);
            return Ok(ChatResponse {
                text: memory_policy_json_for_script(self.script),
                usage: None,
                reasoning_content: None,
                tool_calls: Vec::new(),
            });
        }

        self.main_requests
            .lock()
            .expect("memory e2e provider main requests lock poisoned")
            .push(request.clone());
        let round = self.next_main_index.fetch_add(1, Ordering::SeqCst);
        Ok(memory_agent_e2e_response(self.script, round, &request))
    }

    async fn stream_chat(
        &self,
        request: ChatRequest,
    ) -> anyhow::Result<futures_util::stream::BoxStream<'static, anyhow::Result<StreamChunk>>> {
        let response = self.chat(request).await?;
        let mut chunks = Vec::new();
        if !response.tool_calls.is_empty() {
            chunks.push(Ok(StreamChunk::tool_calls(response.tool_calls)));
        }
        if !response.text.is_empty() {
            chunks.push(Ok(StreamChunk::delta(response.text)));
        }
        chunks.push(Ok(StreamChunk::final_chunk()));
        Ok(futures_util::stream::iter(chunks).boxed())
    }
}

fn is_memory_policy_classifier_request(request: &ChatRequest) -> bool {
    request.messages.iter().any(|message| {
        message
            .content
            .contains("Pioneer memory turn policy classifier")
    })
}

fn memory_policy_json_for_script(script: MemoryAgentE2eScript) -> String {
    let value = match script {
        MemoryAgentE2eScript::ChatCapture => json!({
            "intent": "normal",
            "recall": "allow",
            "prompt": "full",
            "readTools": "allow",
            "rememberTool": "allow",
            "forgetTool": "allow",
            "postTurnExtraction": "disabled",
            "activeMemory": "disabled",
            "explicitRemember": false,
            "explicitForget": false,
            "forgetTargetHint": null,
            "language": "ru",
            "confidence": 0.9,
            "reasonCode": "default_allow_read"
        }),
    };
    serde_json::to_string(&value).expect("policy json should serialize")
}

fn memory_agent_e2e_response(
    script: MemoryAgentE2eScript,
    _round: usize,
    _request: &ChatRequest,
) -> ChatResponse {
    match script {
        MemoryAgentE2eScript::ChatCapture => text_response("Ок."),
    }
}

fn text_response(text: impl Into<String>) -> ChatResponse {
    ChatResponse {
        text: text.into(),
        usage: None,
        reasoning_content: None,
        tool_calls: Vec::new(),
    }
}

fn test_turn_preflight_response() -> ChatResponse {
    test_turn_preflight_response_with_visible_tools(&[])
}

fn test_task_turn_preflight_response() -> ChatResponse {
    test_turn_preflight_response_with_visible_tools(&[
        "task_create",
        "task_wait",
        "task_accept",
        "task_revise",
        "task_cancel",
        "task_update",
        "task_detach",
        "task_list",
        "task_get",
        "task_reschedule",
        "task_pause",
        "task_resume",
    ])
}

fn test_turn_preflight_response_with_visible_tools(tool_names: &[&str]) -> ChatResponse {
    text_response(json!({ "tools": { "visibleTools": tool_names } }).to_string())
}

fn sequenced_tool_provider_preflight_response(
    request: &ChatRequest,
    first_tool_calls: &[ProviderToolCall],
) -> ChatResponse {
    let task_needed = first_tool_calls
        .iter()
        .any(|tool_call| tool_call.name.starts_with("task_"))
        || request
            .messages
            .iter()
            .any(|message| message.content.contains("delegate a task"));

    if task_needed {
        test_task_turn_preflight_response()
    } else {
        test_turn_preflight_response()
    }
}

fn is_turn_preflight_request(request: &ChatRequest) -> bool {
    request.compiled_prompt.is_none()
        && request.tools.is_none()
        && request.tool_choice.is_none()
        && request.messages.len() == 1
        && request.messages[0]
            .content
            .contains("internal turn preflight planner")
        && request.messages[0]
            .content
            .contains("Structured input JSON")
}

fn extract_task_id_from_messages(messages: &[pioneer_provider::ChatMessage]) -> Option<String> {
    for message in messages.iter().rev() {
        if let Ok(value) = serde_json::from_str::<serde_json::Value>(message.content.as_str())
            && let Some(task_id) = value.get("taskId").and_then(serde_json::Value::as_str)
        {
            return Some(task_id.to_owned());
        }
        if let Some(index) = message.content.find("\"taskId\"") {
            let suffix = &message.content[index..];
            if let Some(start) = suffix.find(':') {
                let after_colon = suffix[start + 1..].trim_start();
                if let Some(rest) = after_colon.strip_prefix('"')
                    && let Some(end) = rest.find('"')
                {
                    return Some(rest[..end].to_owned());
                }
            }
        }
    }
    None
}

fn is_child_task_request(request: &ChatRequest) -> bool {
    request.messages.iter().any(|message| {
        message
            .content
            .contains("You are executing a delegated task.")
            || message
                .content
                .contains("You are executing this durable task run now.")
    })
}

fn is_child_task_main_request(request: &ChatRequest) -> bool {
    request.compiled_prompt.is_some() && is_child_task_request(request)
}

#[async_trait::async_trait]
impl Provider for SequencedToolProvider {
    fn name(&self) -> &str {
        "sequenced-tools"
    }

    fn capabilities(&self) -> ProviderCapabilities {
        ProviderCapabilities {
            streaming: false,
            vision: false,
            tool_calling: true,
            embeddings: false,
            transcription: false,
            input_types: ProviderInputCapabilities::fallback_for_all_file_types(),
        }
    }

    async fn chat(&self, request: ChatRequest) -> anyhow::Result<ChatResponse> {
        if is_turn_preflight_request(&request) {
            return Ok(sequenced_tool_provider_preflight_response(
                &request,
                &self.first_tool_calls,
            ));
        }

        self.requests
            .lock()
            .expect("sequenced tool provider lock poisoned")
            .push(request);

        let index = self.next_index.fetch_add(1, Ordering::SeqCst);
        if index == 0 {
            return Ok(ChatResponse {
                text: String::new(),
                usage: None,
                reasoning_content: None,
                tool_calls: self.first_tool_calls.clone(),
            });
        }

        Ok(ChatResponse {
            text: self.second_text.clone(),
            usage: None,
            reasoning_content: None,
            tool_calls: Vec::new(),
        })
    }

    async fn stream_chat(
        &self,
        request: ChatRequest,
    ) -> anyhow::Result<futures_util::stream::BoxStream<'static, anyhow::Result<StreamChunk>>> {
        let response = self.chat(request).await?;
        Ok(futures_util::stream::iter(vec![
            Ok(StreamChunk::delta(response.text)),
            Ok(StreamChunk::final_chunk()),
        ])
        .boxed())
    }
}

fn test_gateway_secrets() -> Arc<GatewaySecrets> {
    Arc::new(GatewaySecrets::new(Arc::new(MemorySecretStore::new())))
}

fn test_gateway_secrets_with_store() -> (Arc<GatewaySecrets>, Arc<MemorySecretStore>) {
    let secret_store = Arc::new(MemorySecretStore::new());
    (
        Arc::new(GatewaySecrets::new(secret_store.clone())),
        secret_store,
    )
}

async fn setup_provider_api_key_processor(
    case_id: &str,
) -> (
    MessageProcessor,
    Arc<MemorySecretStore>,
    mpsc::Receiver<Message>,
    u64,
    Arc<WorkspaceManager>,
    String,
    std::path::PathBuf,
) {
    let session_manager = Arc::new(SessionManager::new());
    let (tx, rx) = mpsc::channel(16);
    let connection_id = session_manager.register_connection(tx).await;
    let thread_manager = Arc::new(ThreadManager::new("test-model", "openai"));
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    let secret_store = Arc::new(MemorySecretStore::new());
    let gateway_secrets = Arc::new(GatewaySecrets::new(secret_store.clone()));
    let base_dir = unique_temp_dir(case_id);
    std::fs::create_dir_all(&base_dir).expect("create settings dir");
    let settings_path = base_dir.join("gateway-settings.toml");
    let processor = MessageProcessor::new(
        thread_manager,
        test_provider(),
        session_manager,
        workspace_manager.clone(),
        crud_store,
        gateway_secrets,
        test_summary_config(),
        test_context_budget(),
        test_tool_loop_config(),
    );

    (
        processor,
        secret_store,
        rx,
        connection_id,
        workspace_manager,
        workspace_id,
        settings_path,
    )
}

#[tokio::test]
async fn provider_api_key_handlers_use_keystore_without_settings_write() {
    let (
        processor,
        secret_store,
        mut rx,
        connection_id,
        workspace_manager,
        workspace_id,
        settings_path,
    ) = setup_provider_api_key_processor("provider_api_key_handlers").await;
    let other_workspace_id = workspace_manager
        .create_workspace("provider_scope_other", Some("Provider Scope Other"))
        .await
        .expect("create other workspace")
        .id;
    let set_request_id =
        pioneer_protocol::RequestId::new(generate_test_request_id("provider", "set"))
            .expect("valid set request id");
    let set_openai_request_id =
        pioneer_protocol::RequestId::new(generate_test_request_id("provider", "set_openai"))
            .expect("valid set openai request id");
    let list_request_id =
        pioneer_protocol::RequestId::new(generate_test_request_id("provider", "list"))
            .expect("valid list request id");
    let other_list_request_id =
        pioneer_protocol::RequestId::new(generate_test_request_id("provider", "list_other"))
            .expect("valid other list request id");
    let delete_request_id =
        pioneer_protocol::RequestId::new(generate_test_request_id("provider", "delete"))
            .expect("valid delete request id");
    let delete_openai_request_id =
        pioneer_protocol::RequestId::new(generate_test_request_id("provider", "delete_openai"))
            .expect("valid delete openai request id");
    let delete_missing_request_id =
        pioneer_protocol::RequestId::new(generate_test_request_id("provider", "missing"))
            .expect("valid missing delete request id");

    processor
        .provider_set_api_key(
            connection_id,
            set_request_id.clone(),
            ProviderSetApiKeyParams {
                workspace_id: workspace_id.clone(),
                provider: "  OpenRouter  ".to_owned(),
                api_key: "sk-secret-provider-key".to_owned(),
            },
        )
        .await;
    let set_response = recv_response_by_id(&mut rx, set_request_id.as_str()).await;
    let set_payload: ProviderSetApiKeyResponse =
        serde_json::from_value(set_response.result).expect("provider/set_api_key payload");
    assert_eq!(set_payload.provider, "openrouter");
    assert!(set_payload.updated);
    assert_eq!(
        secret_store
            .get_string(
                &SecretId::workspace_provider_api_key(workspace_id.as_str(), "openrouter")
                    .expect("provider id"),
            )
            .expect("read provider key"),
        Some("sk-secret-provider-key".to_owned())
    );
    assert!(
        !settings_path.exists(),
        "provider key handler must not write gateway settings"
    );
    processor
        .session_manager
        .set_connection_workspace(connection_id, Some(workspace_id.clone()))
        .await;
    let mut settings_snapshot = pioneer_protocol::GatewaySettingsSnapshot {
        general: Default::default(),
        memory: Default::default(),
        thread_episodic: Default::default(),
        cli_runtimes: Default::default(),
        remote_access: Default::default(),
        voice_input: Default::default(),
    };
    settings_snapshot.thread_episodic.vector_search.enabled = true;
    settings_snapshot.thread_episodic.vector_search.provider =
        Some(pioneer_protocol::GatewayThreadEpisodicVectorProvider::OpenRouter);
    settings_snapshot
        .thread_episodic
        .vector_search
        .provider_key
        .required = true;
    let connection_workspace_id = processor
        .session_manager
        .connection_workspace_id(connection_id)
        .await;
    processor
        .apply_vector_provider_key_presence(
            &mut settings_snapshot,
            connection_workspace_id.as_deref(),
        )
        .expect("settings snapshot key status should apply");
    assert!(
        settings_snapshot
            .thread_episodic
            .vector_search
            .provider_key
            .present
    );
    let settings_snapshot_json =
        serde_json::to_string(&settings_snapshot).expect("settings snapshot serializes");
    assert!(settings_snapshot_json.contains("\"provider_key\""));
    assert!(!settings_snapshot_json.contains("sk-secret-provider-key"));
    assert!(!settings_snapshot_json.contains("api_key"));

    processor
        .provider_set_api_key(
            connection_id,
            set_openai_request_id.clone(),
            ProviderSetApiKeyParams {
                workspace_id: workspace_id.clone(),
                provider: "OpenAI".to_owned(),
                api_key: "sk-openai-embedding-key".to_owned(),
            },
        )
        .await;
    let set_openai_response = recv_response_by_id(&mut rx, set_openai_request_id.as_str()).await;
    let set_openai_payload: ProviderSetApiKeyResponse =
        serde_json::from_value(set_openai_response.result).expect("provider/set openai payload");
    assert_eq!(set_openai_payload.provider, "openai");
    assert!(set_openai_payload.updated);
    assert_eq!(
        secret_store
            .get_string(
                &SecretId::workspace_provider_api_key(workspace_id.as_str(), "openai")
                    .expect("openai provider id"),
            )
            .expect("read openai provider key"),
        Some("sk-openai-embedding-key".to_owned())
    );

    processor
        .provider_list(
            connection_id,
            list_request_id.clone(),
            ProviderListParams {
                workspace_id: workspace_id.clone(),
            },
        )
        .await;
    let list_response = recv_response_by_id(&mut rx, list_request_id.as_str()).await;
    let list_payload: ProviderListResponse =
        serde_json::from_value(list_response.result).expect("provider/list payload");
    let provider_names = list_payload
        .providers
        .iter()
        .map(|provider| provider.name.as_str())
        .collect::<Vec<_>>();
    assert_eq!(provider_names, vec!["local", "openai", "openrouter"]);
    assert!(
        list_payload
            .providers
            .iter()
            .all(|provider| provider.capabilities.embeddings)
    );
    let local_provider = list_payload
        .providers
        .iter()
        .find(|provider| provider.name == "local")
        .expect("provider/list should include the built-in local provider");
    assert!(local_provider.capabilities.transcription);
    assert!(!local_provider.api_key_configured);
    assert!(local_provider.proxy_url.is_none());

    let embedding_models_request_id =
        pioneer_protocol::RequestId::new("provider-embed-models").expect("request id");
    processor
        .provider_list_embedding_models(
            connection_id,
            embedding_models_request_id.clone(),
            ProviderListModelsParams {
                workspace_id: workspace_id.clone(),
                provider: "openai".to_owned(),
            },
        )
        .await;
    let embedding_models_response =
        recv_response_by_id(&mut rx, embedding_models_request_id.as_str()).await;
    let embedding_models_payload: ProviderListModelsResponse =
        serde_json::from_value(embedding_models_response.result)
            .expect("provider/embedding_models/list payload");
    assert_eq!(embedding_models_payload.provider, "openai");
    assert!(
        embedding_models_payload
            .models
            .iter()
            .all(|model| model.capabilities.embeddings == Some(true))
    );
    assert!(
        embedding_models_payload
            .models
            .iter()
            .any(|model| model.id == "text-embedding-3-small")
    );

    processor
        .provider_list(
            connection_id,
            other_list_request_id.clone(),
            ProviderListParams {
                workspace_id: other_workspace_id,
            },
        )
        .await;
    let other_list_response = recv_response_by_id(&mut rx, other_list_request_id.as_str()).await;
    let other_list_payload: ProviderListResponse =
        serde_json::from_value(other_list_response.result).expect("provider/list other payload");
    assert_eq!(other_list_payload.providers.len(), 1);
    let other_local_provider = &other_list_payload.providers[0];
    assert_eq!(other_local_provider.name, "local");
    assert!(other_local_provider.capabilities.embeddings);
    assert!(other_local_provider.capabilities.transcription);
    assert!(!other_local_provider.api_key_configured);
    assert!(other_local_provider.proxy_url.is_none());

    processor
        .provider_delete_api_key(
            connection_id,
            delete_request_id.clone(),
            ProviderDeleteApiKeyParams {
                workspace_id: workspace_id.clone(),
                provider: "OpenRouter".to_owned(),
            },
        )
        .await;
    let delete_response = recv_response_by_id(&mut rx, delete_request_id.as_str()).await;
    let delete_payload: ProviderDeleteApiKeyResponse =
        serde_json::from_value(delete_response.result).expect("provider/delete_api_key payload");
    assert_eq!(delete_payload.provider, "openrouter");
    assert!(delete_payload.deleted);
    assert_eq!(
        secret_store
            .get_string(
                &SecretId::workspace_provider_api_key(workspace_id.as_str(), "openrouter")
                    .expect("provider id"),
            )
            .expect("read deleted provider key"),
        None
    );
    assert_eq!(
        secret_store
            .get_string(
                &SecretId::workspace_provider_api_key(workspace_id.as_str(), "openai")
                    .expect("openai provider id"),
            )
            .expect("read preserved openai provider key"),
        Some("sk-openai-embedding-key".to_owned())
    );
    processor
        .apply_vector_provider_key_presence(
            &mut settings_snapshot,
            connection_workspace_id.as_deref(),
        )
        .expect("settings snapshot key status should apply after delete");
    assert!(
        !settings_snapshot
            .thread_episodic
            .vector_search
            .provider_key
            .present
    );

    processor
        .provider_delete_api_key(
            connection_id,
            delete_missing_request_id.clone(),
            ProviderDeleteApiKeyParams {
                workspace_id: workspace_id.clone(),
                provider: "openrouter".to_owned(),
            },
        )
        .await;
    let missing_delete_response =
        recv_response_by_id(&mut rx, delete_missing_request_id.as_str()).await;
    let missing_delete_payload: ProviderDeleteApiKeyResponse =
        serde_json::from_value(missing_delete_response.result)
            .expect("provider/delete_api_key missing payload");
    assert_eq!(missing_delete_payload.provider, "openrouter");
    assert!(!missing_delete_payload.deleted);

    processor
        .provider_delete_api_key(
            connection_id,
            delete_openai_request_id.clone(),
            ProviderDeleteApiKeyParams {
                workspace_id,
                provider: "openai".to_owned(),
            },
        )
        .await;
    let delete_openai_response =
        recv_response_by_id(&mut rx, delete_openai_request_id.as_str()).await;
    let delete_openai_payload: ProviderDeleteApiKeyResponse =
        serde_json::from_value(delete_openai_response.result)
            .expect("provider/delete_api_key openai payload");
    assert_eq!(delete_openai_payload.provider, "openai");
    assert!(delete_openai_payload.deleted);
}

#[tokio::test]
async fn provider_set_api_key_rejects_empty_key_without_store_write() {
    let (
        processor,
        secret_store,
        mut rx,
        connection_id,
        _workspace_manager,
        workspace_id,
        _settings_path,
    ) = setup_provider_api_key_processor("provider_api_key_empty").await;
    let request_id =
        pioneer_protocol::RequestId::new(generate_test_request_id("provider", "empty"))
            .expect("valid request id");

    processor
        .provider_set_api_key(
            connection_id,
            request_id.clone(),
            ProviderSetApiKeyParams {
                workspace_id,
                provider: "openrouter".to_owned(),
                api_key: "   ".to_owned(),
            },
        )
        .await;

    let error = recv_error_by_id(&mut rx, request_id.as_str()).await;
    assert_eq!(error.error.code, pioneer_protocol::INVALID_PARAMS_CODE);
    let entries = secret_store
        .list(SecretFilter::Kind(SecretKind::ProviderApiKey))
        .expect("list provider keys");
    assert!(entries.is_empty());
}

#[tokio::test]
async fn provider_list_transcription_models_covers_success_and_validation_errors() {
    let (
        processor,
        _secret_store,
        mut rx,
        connection_id,
        _workspace_manager,
        workspace_id,
        _settings_path,
    ) = setup_provider_api_key_processor("provider_list_transcription_models").await;

    let success_id = pioneer_protocol::RequestId::new(generate_test_request_id("tx", "success"))
        .expect("valid success request id");
    processor
        .provider_list_transcription_models(
            connection_id,
            success_id.clone(),
            ProviderListModelsParams {
                workspace_id: workspace_id.clone(),
                provider: "local".to_owned(),
            },
        )
        .await;
    let success = recv_response_by_id(&mut rx, success_id.as_str()).await;
    let payload: ProviderListModelsResponse =
        serde_json::from_value(success.result).expect("transcription model list payload");
    assert_eq!(payload.provider, "local");
    assert_eq!(payload.models.len(), 16);
    assert_eq!(payload.models[0].id, "small");
    assert_eq!(payload.models[6].id, "parakeet-tdt-0.6b-v3");
    assert_eq!(payload.models[15].id, "cohere-int8");
    assert!(
        payload
            .models
            .iter()
            .all(|model| model.capabilities.transcription == Some(true))
    );
    let serialized = serde_json::to_string(&payload).expect("payload should serialize");
    for trusted_value in [
        "blob.handy.computer",
        "sha256",
        "artifact_file_name",
        "install_dir_name",
        "runtime_file_name",
    ] {
        assert!(!serialized.contains(trusted_value));
    }

    let unknown_id = pioneer_protocol::RequestId::new(generate_test_request_id("tx", "unknown"))
        .expect("valid unknown request id");
    processor
        .provider_list_transcription_models(
            connection_id,
            unknown_id.clone(),
            ProviderListModelsParams {
                workspace_id: workspace_id.clone(),
                provider: "not-a-provider".to_owned(),
            },
        )
        .await;
    let unknown = recv_error_by_id(&mut rx, unknown_id.as_str()).await;
    assert_eq!(unknown.error.code, INVALID_REQUEST_CODE);
    assert!(unknown.error.message.contains("failed to create provider"));

    processor
        .provider_registry
        .insert("echo", Arc::new(EchoProvider::new()));
    let unsupported_id =
        pioneer_protocol::RequestId::new(generate_test_request_id("tx", "unsupported"))
            .expect("valid unsupported request id");
    processor
        .provider_list_transcription_models(
            connection_id,
            unsupported_id.clone(),
            ProviderListModelsParams {
                workspace_id: workspace_id.clone(),
                provider: "echo".to_owned(),
            },
        )
        .await;
    let unsupported = recv_error_by_id(&mut rx, unsupported_id.as_str()).await;
    assert_eq!(unsupported.error.code, INVALID_REQUEST_CODE);
    assert!(
        unsupported
            .error
            .message
            .contains("does not support listing transcription models")
    );

    let malformed_id = generate_test_request_id("tx", "malformed");
    processor
        .process_request(
            connection_id,
            &json!({
                "jsonrpc": "2.0",
                "id": malformed_id.clone(),
                "method": pioneer_protocol::constants::methods::PROVIDER_TRANSCRIPTION_MODELS_LIST,
                "params": { "workspace_id": workspace_id }
            })
            .to_string(),
        )
        .await;
    let malformed = recv_error_by_id(&mut rx, malformed_id.as_str()).await;
    assert_eq!(malformed.error.code, pioneer_protocol::INVALID_PARAMS_CODE);

    let unauthorized_id =
        pioneer_protocol::RequestId::new(generate_test_request_id("tx", "workspace"))
            .expect("valid workspace request id");
    processor
        .provider_list_transcription_models(
            connection_id,
            unauthorized_id.clone(),
            ProviderListModelsParams {
                workspace_id: "unknown-workspace".to_owned(),
                provider: "local".to_owned(),
            },
        )
        .await;
    let unauthorized = recv_error_by_id(&mut rx, unauthorized_id.as_str()).await;
    assert_eq!(
        unauthorized.error.code,
        pioneer_protocol::INVALID_PARAMS_CODE
    );
}

