async fn materialize_cli_runtime_approval_turn(
    crud_store: &CrudStore,
    workspace_id: &str,
    thread_id: &str,
    turn_id: &str,
) {
    let now_secs = chrono::Utc::now().timestamp();
    let thread = Thread {
        workspace_id: workspace_id.to_owned(),
        id: thread_id.to_owned(),
        name: Some("CLI approval test".to_owned()),
        preview: String::new(),
        mode: ThreadMode::Agent,
        model: "gpt-5".to_owned(),
        model_provider: "cli_runtime:codex".to_owned(),
        reasoning_effort: None,
        created_at: now_secs,
        updated_at: now_secs,
        status: ThreadStatus::Active,
        origin_kind: ThreadOriginKind::User,
        sidebar_visibility: ThreadSidebarVisibility::Visible,
        agent_nickname: None,
        agent_role: None,
        turns: Vec::new(),
    };
    let turn = Turn {
        id: turn_id.to_owned(),
        status: TurnStatus::InProgress,
        turn_kind: TurnKind::default(),
        origin: TurnOrigin::User,
        error: None,
        prompt_manifest: None,
        permission_profile: default_test_permission_profile(),
    };
    crud_store
        .materialize_turn_start(
            &thread,
            SandboxMode::FullAccess,
            &turn,
            &[UserInput::Text {
                text: "approval".to_owned(),
                text_elements: Vec::new(),
            }],
        )
        .await
        .expect("CLI approval test turn should materialize");
}

